 const wochen=(e.typ==="projekt"?ph.projektSchulwochen:ph.aptSchulwochen).map(swById);
 return {...e,lb:ph.lb,start:wochen[0].start,end:wochen[wochen.length-1].end,praxis:e.praxis||""};
