let qrLogoCache,qrLetzt=null;
function qrLogoLaden(){
 if(qrLogoCache!==undefined)return Promise.resolve(qrLogoCache);
 const laden=src=>new Promise(res=>{const i=new Image();i.onload=()=>res(i);i.onerror=()=>res(null);i.src=src;});
 return laden("logo-quadrat.png").then(async q=>{
  if(q&&q.naturalWidth>0)return{img:q,sx:0,sy:0,sw:q.naturalWidth,sh:q.naturalHeight};
  const j=await laden("logo.jpg");
  return j?{img:j,sx:58,sy:23,sw:139,sh:139}:null;
 }).then(r=>{qrLogoCache=r;return r;});
}
function renderQrCode(){
 const lehrer=isTeacher();
 return`${pageHead("MATERIAL & WERKZEUGE","QR-Code-Generator",lehrer?"Link eingeben und einen QR-Code mit dem Schullogo in der Mitte erzeugen.":"Link eingeben und einen QR-Code erzeugen, den du speichern oder ausdrucken kannst.",`<button class="secondary"onclick="go('lernwerkstatt')">← Lernwerkstatt</button>`)}
 <div class="grid grid-2"style="gap:16px;align-items:start">
  <div class="card"><div class="form">
   <label>Link (Adresse)<input id="qrUrl"type="url"inputmode="url"autocomplete="off"placeholder="https://…"onkeydown="if(event.key==='Enter')qrErzeugen()"></label>
   <label>Beschriftung unter dem Code (optional)<input id="qrText"maxlength="60"placeholder="z. B. Padlet 11Sb"></label>
   <label>Farbe<select id="qrFarbe"><option value="#000000">Schwarz</option><option value="#0f3d6e">Dunkelblau</option></select></label>
   ${lehrer?`<label style="display:flex;gap:8px;align-items:center"><input type="checkbox"id="qrLogo"checked style="width:auto"> Schullogo in der Mitte</label>`:""}
   <div class="form-actions"><button class="primary"onclick="qrErzeugen()">QR-Code erstellen</button><button class="secondary"onclick="qrLoeschen()">Löschen</button></div>
   <p style="font-size:12px;color:var(--muted);margin:0">Tipp: Teste den Code vor dem Ausdrucken mit der Handykamera. Der Link muss ohne Anmeldung erreichbar sein.${lehrer?" Mit Logo bleibt der Code scanbar, weil eine hohe Fehlerkorrektur verwendet wird.":""}</p>
  </div></div>
  <div class="card"style="text-align:center">
   <div id="qrLeer"style="padding:40px 10px;color:var(--muted)">Hier erscheint dein QR-Code.</div>
   <canvas id="qrCanvas"style="display:none;max-width:100%;height:auto;margin:0 auto;border:1px solid var(--line);border-radius:12px;background:#fff"></canvas>
   <div id="qrAktionen"hidden style="display:none;gap:8px;justify-content:center;flex-wrap:wrap;margin-top:12px">
    <button class="primary"onclick="qrHerunterladen()">PNG herunterladen</button>
    <button class="secondary"onclick="qrKopieren()">In Zwischenablage kopieren</button>
    <button class="secondary"onclick="qrLoeschen()">QR-Code löschen</button>
   </div>
  </div>
 </div>
 ${footer()}`;
}
async function qrErzeugen(){
 let url=($("qrUrl")?.value||"").trim();
 if(!url){toast("Bitte einen Link eingeben.");return;}
 if(!/^[a-z][a-z0-9+.-]*:/i.test(url))url="https://"+url;
 try{url=new URL(url).href;}catch(e){toast("Der Link sieht nicht gültig aus.");return;}
 if(!/^https?:/i.test(url)){toast("Bitte einen Link mit http:// oder https:// eingeben.");return;}
 const mitLogo=isTeacher()&&!!$("qrLogo")?.checked;
 const farbe=$("qrFarbe")?.value==="#0f3d6e"?"#0f3d6e":"#000000";
 const text=($("qrText")?.value||"").trim();
 let qr;
 try{qr=qrcode(0,mitLogo?"H":"M");qr.addData(url);qr.make();}catch(e){toast("Der Link ist zu lang für einen QR-Code.");return;}
 const n=qr.getModuleCount(),rand=4,gesamt=n+2*rand,z=Math.max(6,Math.ceil(1000/gesamt)),seite=gesamt*z;
 const schrift=text?Math.round(seite*0.055):0,textH=text?Math.round(schrift*2.1):0;
 const cv=$("qrCanvas");if(!cv)return;
 cv.width=seite;cv.height=seite+textH;
 const ctx=cv.getContext("2d");
 ctx.fillStyle="#ffffff";ctx.fillRect(0,0,cv.width,cv.height);
 ctx.fillStyle=farbe;
 for(let r=0;r<n;r++)for(let c=0;c<n;c++)if(qr.isDark(r,c))ctx.fillRect((c+rand)*z,(r+rand)*z,z,z);
 if(mitLogo){
  const L=await qrLogoLaden();
  if(L){
   const logoS=Math.round(n*z*0.20),pad=Math.max(z,Math.round(logoS*0.08)),x0=Math.round((seite-logoS)/2);
   ctx.fillStyle="#ffffff";
   const rx=x0-pad,rs=logoS+2*pad,rr=Math.round(pad*1.2);
   ctx.beginPath();ctx.moveTo(rx+rr,rx);ctx.arcTo(rx+rs,rx,rx+rs,rx+rs,rr);ctx.arcTo(rx+rs,rx+rs,rx,rx+rs,rr);ctx.arcTo(rx,rx+rs,rx,rx,rr);ctx.arcTo(rx,rx,rx+rs,rx,rr);ctx.closePath();ctx.fill();
   ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality="high";
   ctx.drawImage(L.img,L.sx,L.sy,L.sw,L.sh,x0,x0,logoS,logoS);
  }
 }
 if(text){
  let f=schrift;ctx.fillStyle=farbe;ctx.textAlign="center";ctx.textBaseline="middle";
  do{ctx.font=`700 ${f}px system-ui,Arial,sans-serif`;f-=2;}while(ctx.measureText(text).width>seite*0.9&&f>10);
  ctx.fillText(text,seite/2,seite+textH*0.45);
 }
 let name="link";try{name=new URL(url).hostname.replace(/^www\./,"").replace(/[^a-z0-9]+/gi,"-")||"link";}catch(e){}
 qrLetzt={name};
 cv.style.display="block";
 const leer=$("qrLeer");if(leer)leer.style.display="none";
 const akt=$("qrAktionen");if(akt){akt.hidden=false;akt.style.display="flex";}
}
function qrHerunterladen(){
 const cv=$("qrCanvas");if(!cv||!qrLetzt)return;
 cv.toBlob(b=>{if(!b)return;const a=document.createElement("a");a.href=URL.createObjectURL(b);a.download=`QR-Code-${qrLetzt.name}.png`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),2000);},"image/png");
}
async function qrKopieren(){
 const cv=$("qrCanvas");if(!cv||!qrLetzt)return;
 try{
  const b=await new Promise(r=>cv.toBlob(r,"image/png"));
  await navigator.clipboard.write([new ClipboardItem({"image/png":b})]);
  toast("QR-Code in die Zwischenablage kopiert.");
 }catch(e){toast("Kopieren wird hier nicht unterstützt. Bitte den QR-Code herunterladen.");}
}
function qrLoeschen(){
 const cv=$("qrCanvas");
 if(cv){cv.width=1;cv.height=1;cv.style.display="none";}
 const leer=$("qrLeer");if(leer)leer.style.display="";
 const akt=$("qrAktionen");if(akt){akt.hidden=true;akt.style.display="none";}
 ["qrUrl","qrText"].forEach(id=>{const e=$(id);if(e)e.value="";});
 qrLetzt=null;
}
window.qrLoeschen=qrLoeschen;window.qrErzeugen=qrErzeugen;window.qrHerunterladen=qrHerunterladen;window.qrKopieren=qrKopieren;

function lernplaeneHTML(fortschritte){
 const kachel=f=>{
  const items=combinedTimeline(f.key).filter(t=>t.kind==="woche");
  const c=fachFarbe(f.key);
  const heute=new Date().toISOString().slice(0,10);
  const fertig=items.filter(w=>fortschritte[w.id]?.abgeschlossen).length;
  const prozent=items.length?Math.round(fertig/items.length*100):0;
  const punkte=items.slice(0,60).map(w=>{const ok=fortschritte[w.id]?.abgeschlossen;const jetzt=!ok&&w.start<=heute&&(w.end||w.start)>=heute;
   return`<i title="${esc(w.titel||w.label||"Woche")}"style="width:9px;height:9px;border-radius:50%;display:inline-block;background:${ok?c.border:"#e2eaf0"};${jetzt?`outline:2px solid ${c.border};outline-offset:1px;`:""}"></i>`;}).join("");
  const sub=items.length?`${fertig} von ${items.length} Wochen geschafft`:(f.key==="paedagogik"?"4 Lernbereiche · Projekt + Prüfungstraining":"Lehrplan-Zeitstrahl folgt");
  return`<button class="card tile"style="background:#fff;border:2px solid ${c.border};border-left-width:8px;text-align:left"onclick="openFach('${f.key}')">
 <strong style="font-size:15px;color:${c.text}">${esc(f.label)}</strong>
 <small style="display:block;margin-top:6px">${sub}</small>
 ${items.length?`<div style="height:6px;border-radius:3px;background:#e2eaf0;margin-top:8px;overflow:hidden"><div style="height:100%;width:${prozent}%;background:${c.border}"></div></div><div style="display:flex;flex-wrap:wrap;gap:3px;margin-top:8px">${punkte}</div>`:""}
 </button>`;
 };
 return F11SB_FACHGRUPPEN.map(g=>`<div class="kicker"style="margin:18px 0 10px">${g.title}</div><div class="grid grid-4">${g.keys.map(k=>F11SB_LEHRPLAN_FAECHER.find(f=>f.key===k)).filter(Boolean).map(kachel).join("")}</div>`).join("")+
  (isTeacher()?`<div style="margin-top:14px"><button class="secondary"type="button"onclick="go('didaktik')">Didaktik-Kompass</button></div>`:"");
}
